import { useMemo } from 'react'

import { useSuspenseQuery } from '@tanstack/react-query'

import { getFmPlansByRepo } from '@/api/trainingPlans'
import { useAuth } from '@/contexts/AuthContext'
import type { TrainingPlan } from '@/types/database'

/**
 * 한 레포의 fm:// 플랜을 unit_name 으로 찾는 Map. 조회 중엔 suspend 한다.
 * 폴더 행마다 호출해도 같은 queryKey 라 요청은 한 번만 나간다.
 * 계획 생성/중단/완료 후 목록으로 돌아오면 바로 반영되도록 staleTime 0 (마운트 시 재조회).
 */
export function useFmRepoPlans(owner: string, repo: string) {
  const { user } = useAuth()
  const { data } = useSuspenseQuery({
    queryKey: ['useFmRepoPlans', owner, repo, user?.id],
    queryFn: () => (user ? getFmPlansByRepo(user.id, owner, repo) : []),
    staleTime: 0,
  })
  return useMemo(() => new Map<string, TrainingPlan>(data.map((p) => [p.unit_name, p])), [data])
}
