import { memo, useCallback, type MouseEvent } from 'react'

import { Link } from 'react-router-dom'

import { IconButton, Tooltip } from '@mui/material'

import { PlanAddIcon, PlanIcon } from '@/components/PlanIcons'
import { routes } from '@/routes'

import { useFmRepoPlans } from '../hooks/useFmRepoPlans'
import type { ContentIdentifier } from '../types'

export type ContentPlanButtonProps = Required<ContentIdentifier>

/**
 * flash-man 폴더 행의 훈련 계획 버튼.
 * 이 폴더를 가리키는 계획이 있으면 상세로, 없으면 폴더 정보를 채운 생성 화면으로 보낸다.
 * 상태 색은 PlanCard 의 완료/중단 칩과 같다. 계획 조회 중엔 suspend 하므로 Suspense 로 감싸서 쓴다.
 */
function ContentPlanButton({ owner, repo, path }: ContentPlanButtonProps) {
  const repoPlans = useFmRepoPlans(owner, repo)
  const plan = repoPlans.get(`fm://${owner}/${repo}/${path}`)

  const color = !plan
    ? 'default'
    : plan.completed_at
      ? 'success'
      : plan.paused_at
        ? 'warning'
        : 'primary'
  const statusLabel = plan?.completed_at ? ' (완료)' : plan?.paused_at ? ' (중단)' : ''

  // 버튼 클릭이 행 클릭(폴더 이동/트리 펼침)으로 전파되지 않게 막는다.
  const stopPropagation = useCallback((e: MouseEvent) => e.stopPropagation(), [])

  return (
    <Tooltip title={plan ? `훈련 계획 보기${statusLabel}` : '훈련 계획 추가'}>
      <IconButton
        size="small"
        component={Link}
        to={
          plan
            ? routes.plans.detail.$path({ id: plan.id }, {})
            : routes.plans.new.$({ owner, repo, path })
        }
        color={color}
        onClick={stopPropagation}
        onMouseDown={stopPropagation}
        aria-label={plan ? '훈련 계획 보기' : '훈련 계획 추가'}
      >
        {plan ? <PlanIcon fontSize="small" /> : <PlanAddIcon fontSize="small" />}
      </IconButton>
    </Tooltip>
  )
}

export default memo(ContentPlanButton)
